/* Mascot — animated assistant demo
   7 sprite states, per-emotion CSS motion, squash-and-pop on change,
   cursor-follow 3D lean, typewriter speech, scripted "match recap".
   Sprites are inlined as base64 webp at the bottom of this file. */


const EMOTIONS = {
  idle:    "Ready when you are.",
  worried: "That is a lot of enemy vision on your half of the map.",
  smug:    "Called it. 78% win rate into this matchup.",
  hype:    "PENTAKILL. I am putting that on the highlight reel myself.",
  happy:   "Solid game. CS per minute is up for the fourth match running.",
  sad:     "Twelve deaths. I counted them so you would not have to.",
  annoyed: "You bought boots at 24 minutes. We have discussed this."
};

const sprite = document.getElementById('sprite');
const rig = document.getElementById('rig');
const lineEl = document.getElementById('line');
const controls = document.getElementById('controls');

let current = null;
let typeTimer = null;

function type(text) {
  clearInterval(typeTimer);
  lineEl.textContent = '';
  let i = 0;
  typeTimer = setInterval(() => {
    lineEl.textContent = text.slice(0, ++i);
    if (i >= text.length) clearInterval(typeTimer);
  }, 18);
}

function setEmotion(name) {
  if (name === current) return;
  current = name;
  sprite.src = SPRITES[name];
  sprite.className = 'sprite';
  // force reflow so the pop animation restarts every time
  void sprite.offsetWidth;
  sprite.classList.add('pop');
  sprite.addEventListener('animationend', () => {
    sprite.className = 'sprite m-' + name;
  }, { once: true });
  type(EMOTIONS[name]);
  [...controls.children].forEach(b =>
    b.setAttribute('aria-pressed', String(b.dataset.name === name)));
}

Object.keys(EMOTIONS).forEach(name => {
  const b = document.createElement('button');
  b.textContent = name;
  b.dataset.name = name;
  b.setAttribute('aria-pressed', 'false');
  b.onclick = () => setEmotion(name);
  controls.appendChild(b);
});

/* cursor tracking — he leans toward the pointer */
let tx = 0, ty = 0, cx = 0, cy = 0;
addEventListener('pointermove', e => {
  const r = rig.getBoundingClientRect();
  const dx = (e.clientX - (r.left + r.width / 2)) / innerWidth;
  const dy = (e.clientY - (r.top + r.height / 2)) / innerHeight;
  tx = Math.max(-1, Math.min(1, dx * 2.2));
  ty = Math.max(-1, Math.min(1, dy * 2.2));
});
(function follow() {
  cx += (tx - cx) * 0.08;
  cy += (ty - cy) * 0.08;
  rig.style.transform =
    `rotateY(${cx * 14}deg) rotateX(${-cy * 8}deg) translateX(${cx * 14}px)`;
  requestAnimationFrame(follow);
})();

/* scripted sequence — this is the thing to show on stage */
const SCRIPT = [
  ['idle',    'Loading your last game…',                              1400],
  ['smug',    'Lane phase looks clean. 12 CS ahead at ten minutes.',  3200],
  ['worried', 'Then the enemy jungler shows up. Twice. In a row.',    3200],
  ['sad',     'And the game goes sideways for eleven straight minutes.', 3400],
  ['hype',    'But you found a triple kill at Baron and stole it back!', 3200],
  ['happy',   'Won it. Ugly, but won.',                               2600],
  ['annoyed', 'Next time buy boots before minute twenty.',            3000]
];
let running = false;
document.getElementById('run').onclick = async () => {
  if (running) return;
  running = true;
  for (const [emo, text, ms] of SCRIPT) {
    current = null;
    setEmotion(emo);
    type(text);
    await new Promise(r => setTimeout(r, ms));
  }
  running = false;
};

/* ---------- sprite data (base64 webp, 242x222) ---------- */
const SPRITES = {
"idle": "data:image/webp;base64,",
"worried": "data:image/webp;base64,",
"smug": "data:image/webp;base64,",
"hype": "data:image/webp;base64,",
"happy": "data:image/webp;base64,",
"sad": "data:image/webp;base64,",
"annoyed": "data:image/webp;base64,"
};

setEmotion('idle');